      "measure": "Pinch"
    },
    {
      "name": "Jerk",
      "measure": "Pinch"
    },
    {
      "name": "Salt",
      "measure": "Pinch"
    },
    {
      "name": "Sugar",
      "measure": "Pinch"
    },
    {
      "name": "Black Pepper",
      "measure": "Pinch"
    },
    {
      "name": "Onion",
      "measure": "2 large"
    },
    {
      "name": "Garlic",
      "measure": "4 cloves"
    },
    {
      "name": "Scotch Bonnet",
      "measure": "1"
    },
    {
